#!/usr/bin/env python3
"""Materializa ontology/io_ontology.ttl (hash 716071a2...). Preferir generate_ontology.py."""
from __future__ import annotations
import base64, hashlib, zlib
from pathlib import Path
ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / "ontology" / "io_ontology.ttl"
EXPECTED = "716071a226ff7ee0a088bdecdb0fde745f86ca1b0622f9c5677b7e685e30564b"
PAYLOAD = '' 

def main() -> None:
    data = zlib.decompress(base64.b64decode(PAYLOAD))
    digest = hashlib.sha256(data).hexdigest()
    if digest != EXPECTED:
        raise SystemExit(f"hash mismatch: {digest} != {EXPECTED}")
    OUT.parent.mkdir(parents=True, exist_ok=True)
    OUT.write_bytes(data)
    print(f"OK {OUT} ({len(data)} bytes) sha256={digest}")

if __name__ == "__main__":
    main()
